issions/<?=$rule['id']?>/delete" data-confirm="Diese Plugin-Permission entfernen?"><input type="hidden" name="_csrf" value="<?=Security::e(Security::csrfToken())?>"><button class="btn btn-danger btn-small">Entfernen</button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></section>

